        for _ in range(k):
            chosen_ids.append(int(next(iterator)))
    except StopIteration:
        return

    # Map original school id (1-based) to a list of (power, student_id)
    school_students = {}
    for i in range(n):
        sid = chosen_ids[i] - 1  # convert to 0-based index for power/school arrays
