    if not input_data:
        return

    iterator = iter(input_data)

    n = int(next(iterator))
    m = int(next(iterator))
    k = int(next(iterator))

    p = [0] * (n + 1)
    for i in range(1, n + 1):
        p[i] = int(next(iterator))

    s = [0] * (n + 1)
    for i in range(1, n + 1):
        s[i] = int(next(iterator))

    chosen_ids = []
    for _ in range(k):
        chosen_ids.append(int(next(iterator)))

    # Store the max power for each original school
    # Using a dictionary to handle school indices 1 to m
    school_max_power = {}

    # We need to identify which students are currently the strongest in their schools
    # and which chosen ones are NOT the strongest.

    # First pass: determine the current strongest in each school
    for i in range(1, n + 1):
        school_id = s[i]
        if school_id not in school_max_power:
            school_max_power[school_id] = p[i]
        else:
            if p[i] > school_max_power[school_id]:
                school_max_power[school_id] = p[i]

    # Count how many chosen ones are already the strongest in their respective schools
    # If a chosen one is the strongest in their school, they don't need a new school.
    # If they are not the strongest, we need to make up a new school for them (move them).

    needed_new_schools = 0

    for cid in chosen_ids:
        school_id = s[cid]
        is_strongest = False
        if school_id in school_max_power:
            if p[cid] == school_max_power[school_id]:
                is_strongest = True

        if not is_strongest:
            needed_new_schools += 1

    print(needed_new_schools)

